#requires -Version 5.1
$ErrorActionPreference='Stop'
$module=Import-Module (Join-Path $PSScriptRoot '..\src\WindowsServerMigration.psd1') -Force -PassThru
& $module {param($path) . $path} (Join-Path $PSScriptRoot '..\src\WizardFlow.ps1')
$workspaceRoot=Join-Path ([IO.Path]::GetTempPath()) ('wsm-wizard-flow-'+[Guid]::NewGuid().ToString('N'))
[void][IO.Directory]::CreateDirectory($workspaceRoot)
$passed=0
function Check([bool]$Condition,[string]$Message){if(-not $Condition){throw $Message};$script:passed++}
function Reject([scriptblock]$Action,[string]$Message){$rejected=$false;try{& $Action | Out-Null}catch{$rejected=$true};Check $rejected $Message}
function Private([scriptblock]$Action){
    $wizardPath=Join-Path $PSScriptRoot '..\src\WizardFlow.ps1';$bound=@($args);$code=$Action.ToString()
    & $script:module {param($path,$code,$boundArguments) . $path; $wizardBoundArguments=$boundArguments; Invoke-Expression ('& { '+$code+' } @wizardBoundArguments')} $wizardPath $code $bound
}
function SaveJson($Data,[string]$Path){[IO.File]::WriteAllText($Path,($Data|ConvertTo-Json -Depth 50),(New-Object Text.UTF8Encoding($false)));$Path}
try {
    $empty=Join-Path $workspaceRoot 'empty';$emptyProjection=Private {param($workspace) Get-WsmWizardProjection $workspace '' Manager @()} $empty
    Check ($emptyProjection.intentRequired -and $emptyProjection.actions[0].action -ceq 'ChooseIntent' -and -not (Test-Path -LiteralPath $empty)) 'Opening an uninitialized wizard created role-bound workspace state.'
    $probeOperation=[Guid]::NewGuid().ToString('D');$probeToken=Private {param($workspace,$operation) New-WsmDeveloperProbeCancellationToken -Workspace $workspace -OperationId $operation} $empty $probeOperation;Private {param($token) Request-WsmDeveloperProbeCancellation $token} $probeToken|Out-Null
    $sourceIntentProfile=Private {param($workspace) Initialize-WsmWizardWorkspace $workspace Source} $empty
    Check ($sourceIntentProfile.Role -ceq 'Source' -and (Private {param($workspace) (Read-WsmOutputProfile $workspace).Role} $empty) -ceq 'Source') 'Explicit first-use role intent did not persist across a valid Developer Probe cancellation marker.'
    $unknownProbeRoot=Join-Path $workspaceRoot 'unknown-probe';$unknownRun=Join-Path (Join-Path $unknownProbeRoot 'developer-probes') ([Guid]::NewGuid().ToString('D'));[void][IO.Directory]::CreateDirectory($unknownRun);[IO.File]::WriteAllText((Join-Path $unknownRun 'untrusted.json'),'{}')
    Reject {Private {param($workspace) Initialize-WsmWizardWorkspace $workspace Source} $unknownProbeRoot} 'Role setup accepted unknown Developer Probe output while allowing a cancellation marker.'

    $manager=Join-Path $workspaceRoot 'manager';[void](Initialize-WsmOutputWorkspace -WorkRoot $manager -Role Manager);Initialize-WsmWorkspace $manager | Out-Null
    $source=[pscustomobject]@{HostId=[Guid]::NewGuid().ToString('D');Fingerprint=('a'*64);Name='wizard-fixture-source'}
    $site=New-WsmItem $source.HostId Web IISSite 'Fixture site' 'Default Web Site' @{Xml='<site name="Default Web Site" />'}
    $service=New-WsmItem $source.HostId Services Service 'Fixture service' 'FixtureSvc' @{Name='FixtureSvc';DisplayName='Fixture service';PathName='C:\fixture.exe'}
    $path=New-WsmItem $source.HostId Storage PathCandidate 'Fixture folder' 'D:\data\fixture' @{OriginalPath='D:\data\fixture'}
    $inventory=New-WsmInventory $source 1 @($site,$service,$path);$inventoryPath=Join-Path $workspaceRoot 'source-inventory.json';SaveJson $inventory $inventoryPath|Out-Null
    $catalog=Import-WsmInventory $manager $inventoryPath (Get-FileHash -LiteralPath $inventoryPath -Algorithm SHA256).Hash 'Fixture target'
    $catalog=Enable-WsmAssistiveMode $manager $catalog.PairId $catalog.DecisionRevision

    $first=Private {param($workspace,$pair) Get-WsmWizardState $workspace $pair Manager} $manager $catalog.PairId
    Check ($first.Revision -eq 0 -and $first.ProfileId) 'Wizard state did not start at revision 0 with an enrolled profile binding.'
    $saved=Private {param($workspace,$pair,$revision) Set-WsmWizardState $workspace $pair Manager $revision ([pscustomobject]@{CurrentStep='review';Mode='Automatic';AutoContinue=$true})} $manager $catalog.PairId $first.Revision
    $reopened=Private {param($workspace,$pair) Get-WsmWizardState $workspace $pair Manager} $manager $catalog.PairId
    Check ($reopened.Revision -eq 1 -and $reopened.CurrentStep -ceq 'review' -and $reopened.Mode -ceq 'Automatic' -and $reopened.AutoContinue) 'Wizard state was not durable across reread.'
    Reject {Private {param($workspace,$pair) Set-WsmWizardState $workspace $pair Manager 0 ([pscustomobject]@{CurrentStep='backup'})} $manager $catalog.PairId} 'Stale wizard revision was accepted.'
    Reject {Private {param($workspace,$pair,$revision) Set-WsmWizardState $workspace $pair Manager $revision ([pscustomobject]@{CurrentStep='pretend-success'})} $manager $catalog.PairId $reopened.Revision} 'Unknown wizard step was accepted.'
    Reject {Private {param($workspace,$pair,$revision) Set-WsmWizardState $workspace $pair Manager $revision ([pscustomobject]@{OperationIds=@([Guid]::NewGuid().ToString('D'))})} $manager $catalog.PairId $reopened.Revision} 'Generic wizard state accepted a user-forged operation ID.'
    $jobRoot=Join-Path $manager 'console-jobs';[void][IO.Directory]::CreateDirectory($jobRoot);$durableJob=[pscustomobject]@{jobId=[Guid]::NewGuid().ToString('D');action='ExportPackage';idempotencyKey=[Guid]::NewGuid().ToString('D');RequestHash=('a'*64);workspace=$manager;pairId=$catalog.PairId;role='Manager';status='Running'};SaveJson $durableJob (Join-Path $jobRoot ($durableJob.jobId+'.json'))|Out-Null
    $registeredJob=Private {param($workspace,$job) Register-WsmWizardOperationJob $workspace $job} $manager $durableJob
    $registeredState=Private {param($workspace,$pair) Get-WsmWizardState $workspace $pair Manager} $manager $catalog.PairId
    Check (@($registeredState.OperationIds|Where-Object {$_ -ceq $durableJob.jobId}).Count -eq 1 -and $registeredState.Revision -gt $reopened.Revision) 'A persisted accepted operation job was not registered in the durable wizard state.'
    Reject {Private {param($workspace,$job) Register-WsmWizardOperationJob $workspace $job} $manager ([pscustomobject]@{jobId=[Guid]::NewGuid().ToString('D');action='ExportPackage';idempotencyKey=[Guid]::NewGuid().ToString('D');RequestHash=('b'*64);workspace=$manager;pairId=$catalog.PairId;role='Manager';status='Running'})} 'A foreign job ID without a matching durable console record was registered.'
    Reject {Private {param($workspace,$revision) Set-WsmWizardState $workspace '' Source $revision ([pscustomobject]@{ConfirmedItemIds=@(('a'*64));ConfirmationContext=('b'*64)})} $empty 0} 'Generic wizard progress accepted forged source confirmation state.'

    $projection=Private {param($workspace,$pair) Get-WsmWizardProjection $workspace $pair Manager @()} $manager $catalog.PairId
    Check ($projection.groups.Count -eq 3 -and @($projection.groups|Where-Object kind -CEQ 'website').Count -eq 1 -and @($projection.groups|Where-Object kind -CEQ 'service').Count -eq 1 -and @($projection.groups|Where-Object kind -CEQ 'folder').Count -eq 1) 'Inventory was not projected as business workload groups.'
    $website=$projection.groups|Where-Object kind -CEQ website|Select-Object -First 1
    $choice=Private {param($workspace,$pair,$id,$group,$decision,$selection) Set-WsmWizardChoice -Workspace $workspace -PairId $pair -Role Manager -ItemId $id -GroupId $group -Selected $true -ExpectedDecisionRevision $decision -ExpectedSelectionRevision $selection} $manager $catalog.PairId $website.itemIds[0] $website.groupId $projection.context.catalogRevision $projection.context.selectionRevision
    $after=Get-WsmCatalog $manager $catalog.PairId;$savedItem=@($after.Items|Where-Object ItemId -CEQ $website.itemIds[0])[0];$savedSelection=@($after.Assistive.Selections.Items|Where-Object ItemId -CEQ $website.itemIds[0])[0]
    Check ($savedItem.Decision -ceq 'Include' -and $savedSelection.Selected -and $after.Approval -eq $null) 'Wizard choice bypassed or failed to update native decision/selection state.'
    Check ($choice.AuthoritativeApproval -eq $false) 'Wizard choice was projected as approval.'
    $serviceGroup=$projection.groups|Where-Object kind -CEQ service|Select-Object -First 1
    $exclude=Private {param($workspace,$pair,$id,$group,$decision,$selection) Set-WsmWizardChoice -Workspace $workspace -PairId $pair -Role Manager -ItemId $id -GroupId $group -Selected $false -ExpectedDecisionRevision $decision -ExpectedSelectionRevision $selection} $manager $catalog.PairId $serviceGroup.itemIds[0] $serviceGroup.groupId $after.DecisionRevision $after.Assistive.Selections.Revision
    $automaticState=Private {param($workspace,$pair,$revision) Set-WsmWizardState $workspace $pair Manager $revision ([pscustomobject]@{Mode='Automatic'})} $manager $catalog.PairId $registeredState.Revision
    $autoProjection=Private {param($workspace,$pair) Get-WsmWizardProjection $workspace $pair Manager @()} $manager $catalog.PairId
    $excludedChild=$autoProjection.groups|Where-Object kind -CEQ service|Select-Object -ExpandProperty children|Select-Object -First 1
    Check ($excludedChild.decision -ceq 'Exclude' -and -not $excludedChild.selected -and $excludedChild.confirmed -and $automaticState.Mode -ceq 'Automatic') 'Explicit exclusion was not retained as confirmed when switching to Automatic mode.'
    $automaticProjection=Private {param($workspace,$pair) Get-WsmWizardProjection $workspace $pair Manager @()} $manager $catalog.PairId
    $automaticPriorDecisionRevision=[int]$automaticProjection.context.catalogRevision
    $automaticResult=Private {param($workspace,$pair,$wizard,$decision,$selection,$assistive) Invoke-WsmWizardAutomaticChoices -Workspace $workspace -PairId $pair -Role Manager -ExpectedWizardRevision $wizard -ExpectedDecisionRevision $decision -ExpectedSelectionRevision $selection -ExpectedAssistiveRevision $assistive} $manager $catalog.PairId $automaticProjection.revision $automaticPriorDecisionRevision $automaticProjection.context.selectionRevision $automaticProjection.context.assistiveRevision
    $automaticCatalog=Get-WsmCatalog $manager $catalog.PairId;$automaticFolder=@($automaticCatalog.Items|Where-Object ItemId -CEQ (($projection.groups|Where-Object kind -CEQ folder).itemIds[0]))[0]
    Check (@($automaticResult.AppliedItemIds).Count -eq 1 -and $automaticFolder.Decision -ceq 'Include' -and $automaticResult.AuthoritativeApproval -eq $false -and @($automaticResult.SkippedItemIds).Count -eq 1) 'Automatic manager choice did not apply only the eligible pending item while preserving the exclusion and withholding approval.'
    Check ($automaticResult.CatalogRevision -eq ($automaticPriorDecisionRevision+1) -and @($automaticCatalog.History|Where-Object {$_.Action -ceq 'Decision' -and [int]$_.Revision -eq [int]$automaticResult.CatalogRevision}).Count -eq 1) 'Automatic batch wrote a non-atomic catalog decision revision or duplicate decision history.'
    $automaticCompletedProjection=Private {param($workspace,$pair) Get-WsmWizardProjection $workspace $pair Manager @()} $manager $catalog.PairId
    Check ($automaticCompletedProjection.automaticReviewCurrent -and $automaticCompletedProjection.state.AutomaticReview.Status -ceq 'Completed') 'Current manager automatic review marker was not exposed as current after core choices were saved.'
    Reject {Private {param($workspace,$pair,$wizard,$decision,$selection,$assistive) Invoke-WsmWizardAutomaticChoices -Workspace $workspace -PairId $pair -Role Manager -ExpectedWizardRevision $wizard -ExpectedDecisionRevision $decision -ExpectedSelectionRevision $selection -ExpectedAssistiveRevision $assistive} $manager $catalog.PairId $automaticResult.Revision $automaticResult.CatalogRevision $automaticResult.SelectionRevision $automaticResult.AssistiveRevision} 'Repeated Automatic operation on unchanged revisions was accepted instead of reading its durable completion marker.'
    Reject {Private {param($workspace,$pair,$id,$group,$decision,$selection) Set-WsmWizardChoice -Workspace $workspace -PairId $pair -Role Manager -ItemId $id -GroupId $group -Selected $false -ExpectedDecisionRevision $decision -ExpectedSelectionRevision $selection} $manager $catalog.PairId $website.itemIds[0] $website.groupId 0 0} 'Stale core decision/selection vector was accepted.'
    Reject {Private {param($workspace,$pair,$action) Get-WsmWizardActionDefaults $workspace $pair Manager $action @()} $manager $catalog.PairId 'NotARealWizardAction'} 'Uncurated operation action was accepted.'
    $defaults=Private {param($workspace,$pair,$action) Get-WsmWizardActionDefaults $workspace $pair Manager $action @()} $manager $catalog.PairId 'ApproveMigration'
    Check ($defaults.blocked -and @($defaults.missingFields|Where-Object name -CEQ 'PilotAcknowledgement').Count -eq 1 -and @($defaults.missingFields|Where-Object name -CEQ 'TargetIdentityHash').Count -eq 1) 'Approval defaults fabricated missing target evidence or pilot acknowledgement.'

    $targetRoot=Join-Path $workspaceRoot 'target';$targetProfile=Private {param($workspace) Initialize-WsmWizardWorkspace $workspace Target} $targetRoot
    $targetDefaults=Private {param($workspace) Get-WsmWizardActionDefaults $workspace '' Target Inventory @()} $targetRoot
    Check (-not $targetDefaults.blocked -and $targetDefaults.requiredRole -ceq 'Target' -and $targetDefaults.args.IncludeSoftwareCatalog -and $targetDefaults.args.DeepDiscovery -and $targetDefaults.args.OutputDirectory.StartsWith($targetRoot,[StringComparison]::OrdinalIgnoreCase)) 'Target inventory defaults did not use the enrolled target profile and supported read-only flags.'
    $targetFacts=[pscustomobject]@{HostId=$targetProfile.HostId;Fingerprint=$targetProfile.Fingerprint;Name='fixture-target'}
    $targetInv1=New-WsmInventory $targetFacts 1 @((New-WsmItem $targetFacts.HostId Services Service 'Target service v1' 'TargetSvc' @{Name='TargetSvc'}))
    $targetInv2=New-WsmInventory $targetFacts 2 @((New-WsmItem $targetFacts.HostId Services Service 'Target service v2' 'TargetSvc' @{Name='TargetSvc'}))
    $targetInventoryRoot=Join-Path (Join-Path (Join-Path $targetRoot ('hosts\'+$targetProfile.Fingerprint)) 'inventory') '';[void][IO.Directory]::CreateDirectory($targetInventoryRoot)
    $targetPath1=Join-Path $targetInventoryRoot 'inventory-1.json';$targetPath2=Join-Path $targetInventoryRoot 'inventory-2.json';SaveJson $targetInv1 $targetPath1|Out-Null;SaveJson $targetInv2 $targetPath2|Out-Null
    $targetJob1=[pscustomobject]@{jobId=[Guid]::NewGuid().ToString('D');action='Inventory';status='Succeeded';role='Target';workspace=$targetRoot;CompletedUtc=[DateTime]::UtcNow.ToString('o');outputs=@([pscustomobject]@{Path=$targetPath1;SHA256=(Get-FileHash -LiteralPath $targetPath1 -Algorithm SHA256).Hash})}
    $targetJob2=[pscustomobject]@{jobId=[Guid]::NewGuid().ToString('D');action='Inventory';status='Succeeded';role='Target';workspace=$targetRoot;CompletedUtc=[DateTime]::UtcNow.ToString('o');outputs=@([pscustomobject]@{Path=$targetPath2;SHA256=(Get-FileHash -LiteralPath $targetPath2 -Algorithm SHA256).Hash})}
    $targetJobs=@($targetJob1,$targetJob2);$targetProjection=Private {param($workspace,$jobs) Get-WsmWizardProjection $workspace '' Target $jobs} $targetRoot $targetJobs
    Check ($targetProjection.inventoryCandidates.Count -eq 2 -and -not $targetProjection.scan.hasResult -and @($targetProjection.actions|Where-Object action -CEQ 'SelectInventory').Count -eq 1) 'Multiple durable target inventories were silently resolved by filename or timestamp.'
    $targetBinding=Private {param($workspace,$jobId,$revision,$jobs) Set-WsmWizardInventoryBinding $workspace Target $jobId $revision $jobs} $targetRoot $targetJob2.jobId 0 $targetJobs
    $targetSelected=Private {param($workspace,$jobs) Get-WsmWizardProjection $workspace '' Target $jobs} $targetRoot $targetJobs
    Check ($targetBinding.InventoryRevision -eq 2 -and $targetSelected.inventory.jobId -ceq $targetJob2.jobId -and $targetSelected.scan.hasResult) 'Explicit target inventory binding did not persist the selected durable result.'
    $plainSource=[pscustomobject]@{HostId=[Guid]::NewGuid().ToString('D');Fingerprint=('b'*64);Name='plain-catalog-source'}
    $plainInventory=New-WsmInventory $plainSource 1 @((New-WsmItem $plainSource.HostId Services Service 'Plain service' 'PlainSvc' @{Name='PlainSvc'}))
    $plainPath=Join-Path $workspaceRoot 'plain-inventory.json';SaveJson $plainInventory $plainPath|Out-Null
    $plainCatalog=Import-WsmInventory $manager $plainPath (Get-FileHash -LiteralPath $plainPath -Algorithm SHA256).Hash 'Plain target'
    $plainProjection=Private {param($workspace,$pair) Get-WsmWizardProjection $workspace $pair Manager @()} $manager $plainCatalog.PairId
    Check ($plainProjection.groups.Count -eq 1 -and $plainProjection.results.scan.hasDurableRecord -and $plainProjection.scan.itemCount -eq 1) 'Projection failed for a non-Assistive catalog or omitted its durable scan record.'
    $managerProfile=Private {param($workspace) Read-WsmOutputProfile $workspace} $manager;$approvalOnly=[pscustomobject]@{PairId=$plainCatalog.PairId;InventoryHash=$plainCatalog.InventoryHash;InventoryRevision=$plainCatalog.InventoryRevision;DecisionRevision=$plainCatalog.DecisionRevision;Approval=[pscustomobject]@{Kind='MigrationPlan';ApprovalId=[Guid]::NewGuid().ToString('D');Hash=('c'*64);TargetHostId=[Guid]::NewGuid().ToString('D');TargetFingerprint=('d'*64)}}
    Check (-not (Private {param($workspace,$pair,$profile,$catalog) Get-WsmWizardCurrentApprovedPlan $workspace $pair $profile $catalog @()} $manager $plainCatalog.PairId $managerProfile $approvalOnly)) 'A catalog MigrationPlan marker without its authoritative durable approval job and file was treated as a current approved plan.'
    $stalePlanPath=Join-Path $workspaceRoot 'stale-plan.json';$stalePlan=[pscustomobject]@{SchemaVersion=1;ToolVersion='0.4.0';Kind='MigrationPlan';ToolFingerprint=('e'*64)};SaveJson $stalePlan $stalePlanPath|Out-Null;$stalePlanHash=(Get-FileHash -LiteralPath $stalePlanPath -Algorithm SHA256).Hash.ToLowerInvariant();$approvalOnly.Approval.Hash=$stalePlanHash
    $staleApprovalJob=[pscustomobject]@{jobId=[Guid]::NewGuid().ToString('D');action='ApproveMigration';status='Succeeded';role='Manager';workspace=$manager;pairId=$plainCatalog.PairId;outputs=@([pscustomobject]@{Path=$stalePlanPath;SHA256=$stalePlanHash})}
    Check (-not (Private {param($workspace,$pair,$profile,$catalog,$jobs) Get-WsmWizardCurrentApprovedPlan $workspace $pair $profile $catalog $jobs} $manager $plainCatalog.PairId $managerProfile $approvalOnly @($staleApprovalJob))) 'A durable approval artifact signed by different tool bytes was treated as a current plan.'

    $sourceRoot=Join-Path $workspaceRoot 'source';$sourceWorkspace=Initialize-WsmOutputWorkspace -WorkRoot $sourceRoot -Role Source
    $sourceFacts=[pscustomobject]@{HostId=$sourceWorkspace.Profile.HostId;Fingerprint=$sourceWorkspace.Profile.Fingerprint;Name='bound-local-source'}
    $sourceInventory=New-WsmInventory $sourceFacts 1 @((New-WsmItem $sourceFacts.HostId Web IISSite 'Local site' 'Default Web Site' @{Name='Default Web Site'}),(New-WsmItem $sourceFacts.HostId Services Service 'Local fixture' 'LocalSvc' @{Name='LocalSvc'}),(New-WsmItem $sourceFacts.HostId Storage PathCandidate 'Local folder' 'E:\data' @{OriginalPath='E:\data'}))
    $sourcePath=Join-Path $sourceWorkspace.InventoryDirectory 'inventory-1.json';SaveJson $sourceInventory $sourcePath|Out-Null;$sourceHash=(Get-FileHash -LiteralPath $sourcePath -Algorithm SHA256).Hash.ToLowerInvariant()
    $job=[pscustomobject]@{jobId=[Guid]::NewGuid().ToString('D');action='Inventory';status='Succeeded';role='Source';workspace=$sourceRoot;CompletedUtc=[DateTime]::UtcNow.ToString('o');outputs=@([pscustomobject]@{Path=$sourcePath;SHA256=$sourceHash})}
    $sourceProjection=Private {param($workspace,$jobs) Get-WsmWizardProjection $workspace '' Source $jobs} $sourceRoot @($job)
    Check ($sourceProjection.sourceInventory.sha256 -ceq $sourceHash -and $sourceProjection.groups.Count -eq 3 -and @($sourceProjection.groups|Where-Object { $_.selected -and -not $_.confirmed }).Count -eq 3) 'Source first-use did not preselect discovered groups as unconfirmed intent from the verified durable job output.'
    $eligibilityRoot=Join-Path $workspaceRoot 'eligibility-source';$eligibilityProfile=Private {param($workspace) Initialize-WsmWizardWorkspace $workspace Source} $eligibilityRoot;$eligibilityFacts=[pscustomobject]@{HostId=$eligibilityProfile.HostId;Fingerprint=$eligibilityProfile.Fingerprint;Name='eligibility-source'};$eligibleFolder=New-WsmItem $eligibilityFacts.HostId Storage PathCandidate 'Shared folder' 'D:\shared' @{OriginalPath='D:\shared'};$blockedFolder=New-WsmItem $eligibilityFacts.HostId Storage FileScope 'Shared folder' 'D:\shared' @{OriginalPath='D:\shared'};$blockedFolder.Status='Partial';$eligibilityInventory=New-WsmInventory $eligibilityFacts 1 @($eligibleFolder,$blockedFolder);$eligibilityPath=Join-Path $workspaceRoot 'eligibility-inventory.json';SaveJson $eligibilityInventory $eligibilityPath|Out-Null;$eligibilityHash=(Get-FileHash -LiteralPath $eligibilityPath -Algorithm SHA256).Hash.ToLowerInvariant();$eligibilityJob=[pscustomobject]@{jobId=[Guid]::NewGuid().ToString('D');action='Inventory';status='Succeeded';role='Source';workspace=$eligibilityRoot;CompletedUtc=[DateTime]::UtcNow.ToString('o');outputs=@([pscustomobject]@{Path=$eligibilityPath;SHA256=$eligibilityHash})};$eligibilityGroups=Private {param($items) Get-WsmWizardGroups $items @{} @{} $null} @($eligibilityInventory.Items);$mixedGroup=@($eligibilityGroups|Where-Object {$_.itemIds -contains $eligibleFolder.ItemId})[0]
    Reject {Private {param($workspace,$id,$group,$jobs) Set-WsmWizardChoice -Workspace $workspace -Role Source -ItemId $id -GroupId $group -Selected $true -ExpectedDecisionRevision 1 -ExpectedSelectionRevision 0 -ExpectedWizardRevision 0 -Jobs $jobs} $eligibilityRoot $eligibleFolder.ItemId $mixedGroup.groupId @($eligibilityJob)} 'Source choice accepted a mixed group containing an incomplete item.'
    Reject {Private {param($workspace,$id,$jobs) Set-WsmWizardChoice -Workspace $workspace -Role Source -ItemId $id -Selected $true -ExpectedDecisionRevision 1 -ExpectedSelectionRevision 0 -ExpectedWizardRevision 0 -Jobs $jobs} $eligibilityRoot $blockedFolder.ItemId @($eligibilityJob)} 'Source choice accepted a directly selected incomplete item.'
    $sourceChoice=Private {param($workspace,$id,$revision,$jobs) Set-WsmWizardChoice -Workspace $workspace -Role Source -ItemId $id -Selected $false -Reason '' -ExpectedDecisionRevision $revision -ExpectedSelectionRevision 0 -ExpectedWizardRevision 0 -Jobs $jobs} $sourceRoot $sourceInventory.Items[0].ItemId 1 @($job)
    Check ($sourceChoice.SourceIntent.Count -eq 1 -and -not $sourceChoice.SourceIntent[0].Selected -and $sourceChoice.SourceIntent[0].Reason) 'Unbound source choice was not persisted as explicit intent.'
    $resumedSource=Private {param($workspace,$jobs) Get-WsmWizardProjection $workspace '' Source $jobs} $sourceRoot @($job)
    Check (@($resumedSource.groups|Where-Object { $_.confirmed }).Count -eq 1 -and @($resumedSource.groups|Where-Object { $_.selected -and -not $_.confirmed }).Count -eq 2) 'Source scan restart did not distinguish saved intent from preselected, unconfirmed remainder.'
    $sourceRemainder=Private {param($workspace,$wizard,$jobs) Invoke-WsmWizardAutomaticChoices -Workspace $workspace -Role Source -ExpectedWizardRevision $wizard -ExpectedDecisionRevision 1 -ExpectedSelectionRevision $wizard -Jobs $jobs -ConfirmRemainingChoices} $sourceRoot $resumedSource.revision @($job)
    Check ($sourceRemainder.Status -ceq 'SavedRemainder' -and $sourceRemainder.Mode -ceq 'ItemByItem' -and @($sourceRemainder.AppliedItemIds).Count -eq 2) 'Confirm remaining source choices did not preserve ItemByItem mode or apply the eligible remainder.'
    $sourceAutomatic=Private {param($workspace,$wizard,$jobs) Invoke-WsmWizardAutomaticChoices -Workspace $workspace -Role Source -ExpectedWizardRevision $wizard -ExpectedDecisionRevision 1 -ExpectedSelectionRevision $wizard -Jobs $jobs} $sourceRoot $sourceRemainder.Revision @($job)
    $sourceAutomaticProjection=Private {param($workspace,$jobs) Get-WsmWizardProjection $workspace '' Source $jobs} $sourceRoot @($job)
    Check (@($sourceAutomatic.AppliedItemIds).Count -eq 2 -and @($sourceAutomaticProjection.groups|Where-Object { $_.confirmed -and $_.selected }).Count -eq 2 -and @($sourceAutomaticProjection.groups|Where-Object { $_.confirmed -and -not $_.selected }).Count -eq 1 -and -not $sourceAutomatic.AuthoritativeApproval) 'Source automatic intent did not save only eligible remaining choices while preserving an explicit exclusion.'
    $handoff=Private {param($workspace,$jobs) Export-WsmWizardSourceReviewHandoff -Workspace $workspace -Jobs $jobs} $sourceRoot @($job)
    Check ($handoff.Status -ceq 'Succeeded' -and $handoff.HandoffStatus -ceq 'Exported' -and $handoff.AuthoritativeApproval -eq $false -and $handoff.SourceInventoryHash -ceq $sourceHash -and $handoff.ConfirmedChoiceCount -eq 3 -and (Test-Path -LiteralPath $handoff.Path)) 'Source handoff did not persist the verified inventory and confirmed, non-authoritative choices.'
    $handoffManager=Join-Path $workspaceRoot 'handoff-manager';[void](Initialize-WsmOutputWorkspace -WorkRoot $handoffManager -Role Manager);Initialize-WsmWorkspace $handoffManager|Out-Null
    $handoffImport=Private {param($workspace,$path,$hash) Import-WsmWizardSourceReviewHandoff -Workspace $workspace -Path $path -ExpectedHash $hash -TargetName 'Handoff target'} $handoffManager $handoff.Path $handoff.SHA256
    $handoffCatalog=Private {param($workspace,$pair) Get-WsmCatalog $workspace $pair} $handoffManager $handoffImport.PairId
    $handoffExcluded=@($handoffCatalog.Items|Where-Object Decision -CEQ Exclude);$handoffIncluded=@($handoffCatalog.Items|Where-Object Decision -CEQ Include);$handoffAssistive=Private {param($current) (Get-WsmAssistiveCurrentSelections $current).Items} $handoffCatalog
    Check ($handoffImport.Status -ceq 'Succeeded' -and $handoffImport.PairId -and $handoffImport.AuthoritativeApproval -eq $false -and $handoffImport.AppliedChoiceCount -eq 3 -and $handoffCatalog.SourceReviewHandoff.HandoffHash -ceq $handoff.SHA256 -and $handoffExcluded.Count -eq 1 -and $handoffIncluded.Count -eq 2 -and @($handoffCatalog.Items|Where-Object Decision -CEQ Pending).Count -eq 0 -and @($handoffAssistive|Where-Object {$_.Selected}).Count -eq 2) 'Manager import did not consume the exact source choices into durable core decisions/selections and record non-approval provenance.'
    $unrelatedId=[string]$handoffExcluded[0].ItemId;$includedId=[string]$handoffIncluded[0].ItemId;$currentAssistiveRevision=[int]$handoffCatalog.Assistive.Revision
    Private {param($workspace,$pair,$revision,$id) Set-WsmAssistiveSelections -Workspace $workspace -PairId $pair -ExpectedRevision $revision -ItemIds @($id) -Selected $true -Reason 'Preserve existing Manager selection'} $handoffManager $handoffImport.PairId $currentAssistiveRevision $unrelatedId | Out-Null
    $partialHandoff=Private {param($path) Read-WsmJson $path} $handoff.Path;$partialHandoff.Choices=@($partialHandoff.Choices|Where-Object ItemId -CEQ $includedId);$partialInventory=Private {param($json) ConvertFrom-WsmJson $json} ([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String([string]$partialHandoff.InventoryBase64)));$partialInventory.Revision=2;$partialInventoryBytes=[Text.Encoding]::UTF8.GetBytes(($partialInventory|ConvertTo-Json -Depth 100 -Compress));$partialInventoryPath=Join-Path $workspaceRoot 'partial-source-inventory.json';[IO.File]::WriteAllBytes($partialInventoryPath,$partialInventoryBytes);$partialInventoryHash=(Get-FileHash -LiteralPath $partialInventoryPath -Algorithm SHA256).Hash.ToLowerInvariant();$partialHandoff.InventoryRevision=2;$partialHandoff.InventoryHash=$partialInventoryHash;$partialHandoff.InventoryBase64=[Convert]::ToBase64String($partialInventoryBytes);foreach($choice in $partialHandoff.Choices){$choice.InventoryRevision=2;$choice.InventoryHash=$partialInventoryHash};$partialHandoffPath=Join-Path $workspaceRoot 'partial-source-handoff.json';SaveJson $partialHandoff $partialHandoffPath|Out-Null;$partialHandoffHash=(Get-FileHash -LiteralPath $partialHandoffPath -Algorithm SHA256).Hash.ToLowerInvariant()
    $partialImport=Private {param($workspace,$path,$hash) Import-WsmWizardSourceReviewHandoff -Workspace $workspace -Path $path -ExpectedHash $hash -TargetName 'Handoff target'} $handoffManager $partialHandoffPath $partialHandoffHash
    $partialCatalog=Private {param($workspace,$pair) Get-WsmCatalog $workspace $pair} $handoffManager $handoffImport.PairId;$partialSelection=Private {param($current,$id) @((Get-WsmAssistiveCurrentSelections $current).Items|Where-Object ItemId -CEQ $id)[0]} $partialCatalog $unrelatedId
    Check ($partialImport.AppliedChoiceCount -eq 1 -and $partialSelection.Selected -and $partialSelection.Reason -ceq 'Preserve existing Manager selection' -and @($partialCatalog.History|Where-Object Action -CEQ SourceReviewHandoff|Select-Object -Last 1)[0].Before.Count -eq 1) 'A partial source handoff changed unrelated Manager selections or omitted the prior decision from audit history.'
    $badHandoff=Private {param($path) Read-WsmJson $path} $handoff.Path;$badHandoff.Choices[0].ItemId='unknown-item';$badHandoffPath=Join-Path $workspaceRoot 'bad-source-handoff.json';SaveJson $badHandoff $badHandoffPath|Out-Null;$badHandoffHash=(Get-FileHash -LiteralPath $badHandoffPath -Algorithm SHA256).Hash.ToLowerInvariant()
    Reject {Private {param($workspace,$path,$hash) Import-WsmWizardSourceReviewHandoff -Workspace $workspace -Path $path -ExpectedHash $hash -TargetName 'Bad target'} $handoffManager $badHandoffPath $badHandoffHash} 'Handoff import accepted a confirmed choice for an unknown inventory item.'
    $blankReason=Private {param($path) Read-WsmJson $path} $handoff.Path;$blankReason.Choices=@($blankReason.Choices|ForEach-Object {$copy=$_|Select-Object *;if(-not $copy.Selected){$copy.Reason='  '};$copy});$blankReasonPath=Join-Path $workspaceRoot 'blank-source-handoff.json';SaveJson $blankReason $blankReasonPath|Out-Null;$blankReasonHash=(Get-FileHash -LiteralPath $blankReasonPath -Algorithm SHA256).Hash.ToLowerInvariant();$blankManager=Join-Path $workspaceRoot 'blank-manager';[void](Initialize-WsmOutputWorkspace -WorkRoot $blankManager -Role Manager);Initialize-WsmWorkspace $blankManager|Out-Null
    Reject {Private {param($workspace,$path,$hash) Import-WsmWizardSourceReviewHandoff -Workspace $workspace -Path $path -ExpectedHash $hash -TargetName 'Blank reason'} $blankManager $blankReasonPath $blankReasonHash} 'Handoff accepted an exclusion with a blank reason.'
    $blankFleet=Private {param($workspace) Get-WsmFleet $workspace} $blankManager;$blankImportedPath=Join-Path (Join-Path (Join-Path (Join-Path $blankManager 'workspace-control') 'wizard-materials') 'source-review-imports') ($handoff.SourceInventoryHash+'.json')
    Check (@($blankFleet.Pairs).Count -eq 0 -and -not (Test-Path -LiteralPath $blankImportedPath)) 'Invalid handoff left imported inventory or pair state behind.'
    Reject {Private {param($workspace,$wizard,$jobs) Invoke-WsmWizardAutomaticChoices -Workspace $workspace -Role Source -ExpectedWizardRevision $wizard -ExpectedDecisionRevision 1 -ExpectedSelectionRevision $wizard -Jobs $jobs} $sourceRoot $sourceAutomatic.Revision @($job)} 'Repeated Source automatic operation on unchanged intent was accepted instead of reading its durable completion marker.'
    $changedInventory=New-WsmInventory $sourceFacts 2 @((New-WsmItem $sourceFacts.HostId Web IISSite 'Local site' 'Default Web Site' @{Name='Default Web Site';PhysicalPath='D:\changed-site'}),(New-WsmItem $sourceFacts.HostId Services Service 'Local fixture' 'LocalSvc' @{Name='LocalSvc'}),(New-WsmItem $sourceFacts.HostId Storage PathCandidate 'New folder' 'F:\new-data' @{OriginalPath='F:\new-data'}))
    $changedPath=Join-Path $sourceWorkspace.InventoryDirectory 'inventory-2.json';SaveJson $changedInventory $changedPath|Out-Null;$changedHash=(Get-FileHash -LiteralPath $changedPath -Algorithm SHA256).Hash.ToLowerInvariant();$changedJob=[pscustomobject]@{jobId=[Guid]::NewGuid().ToString('D');action='Inventory';status='Succeeded';role='Source';workspace=$sourceRoot;CompletedUtc=[DateTime]::UtcNow.ToString('o');outputs=@([pscustomobject]@{Path=$changedPath;SHA256=$changedHash})}
    $rebound=Private {param($workspace,$role,$jobId,$revision,$jobs) Set-WsmWizardInventoryBinding -Workspace $workspace -Role $role -JobId $jobId -ExpectedWizardRevision $revision -Jobs $jobs} $sourceRoot 'Source' $changedJob.jobId $sourceAutomatic.Revision @($job,$changedJob)
    $reboundProjection=Private {param($workspace,$jobs) Get-WsmWizardProjection $workspace '' Source $jobs} $sourceRoot @($job,$changedJob)
    $reboundSite=@($reboundProjection.groups|Where-Object kind -CEQ website)[0].children[0];$reboundService=@($reboundProjection.groups|Where-Object kind -CEQ service)[0].children[0];$reboundFolders=@($reboundProjection.groups|Where-Object kind -CEQ folder)
    Check ($reboundProjection.sourceInventory.sha256 -ceq $changedHash -and @($reboundProjection.groups).Count -eq 3 -and -not $reboundSite.selected -and -not $reboundSite.confirmed -and $reboundService.selected -and $reboundService.confirmed -and $reboundFolders.Count -eq 1 -and $reboundFolders[0].selected -and -not $reboundFolders[0].confirmed) 'Re-scan failed to preserve the matching exclusion, retain unchanged confirmed choices, drop removed items, and leave new items unconfirmed.'
    Check (-not $reboundProjection.automaticReviewCurrent -and -not $reboundProjection.state.AutomaticReview -and -not $reboundProjection.remainderReviewCurrent -and -not $reboundProjection.state.RemainderReview) 'A completed source marker from an earlier scan remained visible after inventory rebinding.'
    $spoof=$job|Select-Object *;$spoof.outputs=@([pscustomobject]@{Path=$sourcePath;SHA256=('f'*64)})
    $spoofProjection=Private {param($workspace,$jobs) Get-WsmWizardProjection $workspace '' Source $jobs} $sourceRoot @($spoof)
    Check (-not $spoofProjection.sourceInventory) 'Source projection trusted a durable job whose output hash did not match bytes.'
    Write-Host ('PASS: '+$passed+' WizardFlow state, CAS, role binding, workload grouping, core choices, curated defaults, source job provenance and negative checks.')
} finally {Remove-Item -LiteralPath $workspaceRoot -Recurse -Force}
